...[['shirt','Linen day shirt',55],['hoodie','Cloud-pocket hoodie',85],['jacket','Archivist jacket',90],['dress','Wildflower dress',80],['pajamas','Stargazer pajamas',75],['costume','Honeybee costume',110]].map(([id,name,price])=>({id,name,price,type:'Clothes',desc:'Tailored sprite layer with stitched detail and highlighted seams.'})),
