// Curated inventory: one free item, 2–3 coin items, and two Plus previews per category.
const curatedShop={Characters:{free:'bunny',coins:['cat','dragon'],plus:['fox','alien']},Clothing:{free:'shirt',coins:['overalls','costume'],plus:['jacket','galaxy']},Accessories:{free:'bow',coins:['hat','headphones','scarf'],plus:['beanie','crown']},'Diabetes devices':{free:'cgm',coins:['pump','starpatch'],plus:['brassclip','petalset']},Worlds:{free:'cozy',coins:['cyber','snow','beach'],plus:['library','garden']},Themes:{free:'pastel',coins:['academia','cottagecore'],plus:['arcade','nighttheme']}};
function configureCuratedShop(){for(const group of Object.values(curatedShop)){for(const id of [group.free,...group.coins,...group.plus]){const item=items.find(i=>i.id===id);if(item){item.premium=group.plus.includes(id);if(id===group.free)item.price=0}}}}
const curatedIds=new Set(Object.values(curatedShop).flatMap(g=>[g.free,...g.coins,...g.plus]));
let previewSelection=null,ownedOnly=false;
const shopGroup=i=>i.type==='Rooms'?'Worlds':i.type==='Clothes'?'Clothing':['Eyewear','Scarves'].includes(i.type)?'Accessories':i.type==='Devices'?'Diabetes devices':i.type;
function previewEquipment(item){return item?{...state.equipped,[itemSlot(item)]:item.id}:state.equipped}
function pixelShop(){const selected=items.find(i=>i.id===previewSelection);const groups=['Characters','Clothing','Diabetes devices'];if(!groups.includes(category))category='Characters';const list=items.filter(i=>curatedIds.has(i.id)&&shopGroup(i)===category&&(!ownedOnly||state.owned.includes(i.id)));content.innerHTML=greeting('A wardrobe of possibilities','Change your buddy’s clothes, devices, and character.','DiaBuddy · THE LITTLE EMPORIUM')+`<div class="pixel-shop"><section class="card fitting-room"><div class="eyebrow">THE FITTING ROOM · LIVE PREVIEW</div><canvas id="fitting-preview" width="640" height="400" aria-label="Live character and item preview"></canvas><div class="fitting-copy"><h2>${escapeHTML(selected?.name||buddyName())}</h2><p>${escapeHTML(selected?.desc||'Choose an item to try it on. Your saved outfit changes only when you equip it.')}</p><div class="item-state">${selected?(selected.premium?'PLUS COLLECTION':state.equipped[itemSlot(selected)]===selected.id?'EQUIPPED':state.owned.includes(selected.id)?'OWNED · READY TO EQUIP':'LOCKED · '+selected.price+' COINS'):'YOUR CURRENT LOOK'}</div><div id="fitting-actions">${selected?shopAction(selected):'<button class="secondary" id="rename-fit">Rename companion · Free</button>'}</div><button class="text-link" id="clear-preview">Back to my current look</button></div><div class="outfit-slots">${Object.entries(state.equipped).map(([slot,id])=>`<span>${escapeHTML(items.find(i=>i.id===id)?.name||id)} <button aria-label="Remove ${escapeHTML(slot)}" data-remove="${escapeHTML(slot)}">×</button></span>`).join('')}</div></section><div class="shop-collection"><div class="tabs">${groups.map(g=>`<button data-shopgroup="${g}" class="${category===g?'selected':''}">${g}</button>`).join('')}</div><label class="owned-toggle"><input type="checkbox" id="owned-only" ${ownedOnly?'checked':''}> My collection only <span>${state.coins} coins available</span></label><div class="pixel-products">${list.map(i=>`<section class="card pixel-product ${selected?.id===i.id?'is-previewed':''}"><button class="pixel-thumb" data-try="${i.id}" aria-label="Try ${escapeHTML(i.name)}"><canvas width="320" height="200" data-pixel-item="${i.id}"></canvas><span>${i.premium?'PLUS':state.equipped[itemSlot(i)]===i.id?'EQUIPPED':state.owned.includes(i.id)?'OWNED':'LOCKED'}</span></button><div class="product-copy"><small>${shopGroup(i)}</small><h3>${escapeHTML(i.name)}</h3><p>${i.premium?'Plus preview':state.owned.includes(i.id)?'In your collection':i.price+' coins'}</p>${shopAction(i)}</div></section>`).join('')||'<p>No items in this collection yet.</p>'}</div></div></div>`;
paintWorld($('#fitting-preview'),selected?.type==='Rooms'?selected.id:state.equipped.Rooms||'cozy',previewEquipment(selected),'range','Trying on accessories',false,false,Date.now());document.querySelectorAll('[data-pixel-item]').forEach(canvas=>{const i=items.find(x=>x.id===canvas.dataset.pixelItem);paintWorld(canvas,i.type==='Rooms'?i.id:state.equipped.Rooms||'cozy',previewEquipment(i),'range','Idle',true,!['Rooms','Themes'].includes(i.type))});
document.querySelectorAll('[data-shopgroup]').forEach(b=>b.onclick=()=>{category=b.dataset.shopgroup;pixelShop()});document.querySelectorAll('[data-try]').forEach(b=>b.onclick=()=>{previewSelection=b.dataset.try;tryOnUntil=Date.now()+1600;pixelShop()});document.querySelectorAll('[data-purchase]').forEach(b=>b.onclick=()=>buyPixelItem(b.dataset.purchase));document.querySelectorAll('[data-equip-pixel]').forEach(b=>b.onclick=()=>{const i=items.find(x=>x.id===b.dataset.equipPixel);if(!state.owned.includes(i.id))return;state.equipped[itemSlot(i)]=i.id;tryOnUntil=Date.now()+1800;save();pixelShop();toast(i.name+' equipped.')});document.querySelectorAll('[data-plus-link]').forEach(b=>b.onclick=()=>showModal('<div class="eyebrow">PLUS PREVIEW</div><h2>A little extra, someday.</h2><p>This item is a preview. Plus subscriptions and payments are not available in this prototype.</p>'));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const slot=b.dataset.remove;if(slot==='Characters')state.equipped.Characters='bunny';else delete state.equipped[slot];save();pixelShop()});$('#owned-only').onchange=e=>{ownedOnly=e.target.checked;pixelShop()};$('#clear-preview').onclick=()=>{previewSelection=null;pixelShop()};if($('#rename-fit'))$('#rename-fit').onclick=renameCharacter;window.FamilyRewards?.mountShop();
}
function shopAction(i){if(i.premium)return'<button class="secondary" data-plus-link="'+i.id+'">Plus item · preview</button>';if(state.equipped[itemSlot(i)]===i.id)return'<button class="secondary" disabled>Equipped ✓</button>';if(state.owned.includes(i.id))return'<button class="primary" data-equip-pixel="'+i.id+'">Equip item</button>';return'<button class="primary" data-purchase="'+i.id+'" '+(state.coins<i.price?'disabled':'')+'>Buy · '+i.price+' coins</button>'}
function buyPixelItem(id){const i=items.find(x=>x.id===id);if(!i||i.premium||state.owned.includes(id)||state.coins<i.price)return false;state.coins-=i.price;state.owned.push(id);previewSelection=id;save();pixelShop();toast(i.name+' added to your collection.');return true}
